import json
import itertools

def solve_puzzle():
    # Input variables
    houses = [1, 2, 3, 4]
    names = ["Eric", "Arnold", "Alice", "Peter"]
    styles = ["craftsman", "colonial", "ranch", "victorian"]

    solutions = []

    # Iterate over permutations for names assigned to houses (house -> name)
    # Apply clue 1 early: Alice is in the second house (house index 2)
    for name_at_house in itertools.permutations(names):
        if name_at_house[1] != "Alice":
            continue  # Clue 1

        pos_name = {name: idx + 1 for idx, name in enumerate(name_at_house)}

        # Iterate over permutations for styles assigned to houses (house -> style)
        for style_at_house in itertools.permutations(styles):
            pos_style = {style: idx + 1 for idx, style in enumerate(style_at_house)}

            # Clue 5: The person in a Craftsman-style house is Alice.
            # Since Alice is in house 2, craftsman must be at house 2.
            if pos_style["craftsman"] != pos_name["Alice"]:
                continue

            # Clue 4: Arnold is somewhere to the right of the person in a Craftsman-style house.
            if not (pos_name["Arnold"] > pos_style["craftsman"]):
                continue

            # Clue 2: The person residing in a Victorian house is directly left of Peter.
            if not (pos_style["victorian"] + 1 == pos_name["Peter"]):
                continue

            # Clue 3: Peter is somewhere to the right of the person in a ranch-style home.
            if not (pos_name["Peter"] > pos_style["ranch"]):
                continue

            # If all constraints are satisfied, record the solution
            solution_rows = []
            for h in houses:
                solution_rows.append([
                    str(h),
                    name_at_house[h - 1],
                    style_at_house[h - 1],
                ])
            solutions.append(solution_rows)

    # Choose the first solution if multiple found
    if not solutions:
        raise ValueError("No solution found.")
    final_rows = solutions[0]

    output = {
        "solution": {
            "header": ["House", "Name", "HouseStyle"],
            "rows": final_rows
        }
    }
    return output

if __name__ == "__main__":
    result = solve_puzzle()
    print(json.dumps(result, ensure_ascii=False, indent=2))
